#include <iostream>
#include <string>
#include <vector>
#include <ldap.h>
#include <cstring>

std::string constructBaseDN(const std::vector<std::string>& dcComponents) {
    std::string baseDN;
    for (size_t i = 0; i < dcComponents.size(); ++i) {
        if (i > 0) baseDN += ",";
        baseDN += "dc=" + dcComponents[i];
    }
    return baseDN;
}

std::string constructFilter(const std::string& username) {
    return "(uid=" + username + ")";
}

int searchUser(const std::string& username, const std::vector<std::string>& dcComponents) {
    std::string baseDN = constructBaseDN(dcComponents);
    std::string filter = constructFilter(username);

    LDAP* ld = nullptr;
    int rc = ldap_initialize(&ld, "ldap://localhost");
    if (rc != LDAP_SUCCESS) {
        std::cerr << "ldap_initialize failed: " << ldap_err2string(rc) << std::endl;
        return 1;
    }

    // Set protocol version to 3
    int version = LDAP_VERSION3;
    ldap_set_option(ld, LDAP_OPT_PROTOCOL_VERSION, &version);

    // Anonymous bind
    rc = ldap_simple_bind(ld, nullptr, nullptr);
    if (rc != LDAP_SUCCESS) {
        std::cerr << "ldap_simple_bind failed: " << ldap_err2string(rc) << std::endl;
        ldap_unbind_ext(ld, nullptr, nullptr);
        return 1;
    }

    // Search
    char* attrs[] = {const_cast<char*>("*"), nullptr};
    LDAPMessage* result = nullptr;
    rc = ldap_search_ext_s(ld, baseDN.c_str(), LDAP_SCOPE_SUBTREE, filter.c_str(), attrs, 0, nullptr, nullptr, nullptr, 0, &result);

    if (rc != LDAP_SUCCESS) {
        std::cerr << "ldap_search_ext_s failed: " << ldap_err2string(rc) << std::endl;
        ldap_unbind_ext(ld, nullptr, nullptr);
        return 1;
    }

    // Iterate through entries
    LDAPMessage* entry = ldap_first_entry(ld, result);
    if (entry == nullptr) {
        std::cout << "No user found" << std::endl;
    } else {
        while (entry != nullptr) {
            char* dn = ldap_get_dn(ld, entry);
            std::cout << "DN: " << (dn ? dn : "unknown") << std::endl;
            if (dn) ldap_memfree(dn);

            BerElement* ber = nullptr;
            char* attr = ldap_first_attribute(ld, entry, &ber);
            while (attr != nullptr) {
                char** vals = ldap_get_values(ld, entry, attr);
                if (vals != nullptr) {
                    for (int i = 0; vals[i] != nullptr; ++i) {
                        std::cout << attr << ": " << vals[i] << std::endl;
                    }
                    ldap_value_free(vals);
                }
                ldap_memfree(attr);
                attr = ldap_next_attribute(ld, entry, ber);
            }
            if (ber) ber_free(ber, 0);

            std::cout << "---" << std::endl;
            entry = ldap_next_entry(ld, entry);
        }
    }

    ldap_msgfree(result);
    ldap_unbind_ext(ld, nullptr, nullptr);
    return 0;
}

int main(int argc, char* argv[]) {
    if (argc < 3) {
        std::cerr << "Usage: " << argv[0] << " <username> <dc1> [dc2] [dc3] ..." << std::endl;
        return 1;
    }

    std::string username = argv[1];
    std::vector<std::string> dcComponents;
    for (int i = 2; i < argc; ++i) {
        dcComponents.push_back(argv[i]);
    }

    return searchUser(username, dcComponents);
}
